     1→'use client'
     2→
     3→import { useState, useEffect, useRef } from 'react'
     4→import { SyncClient } from 'twilio-sync'
     5→
     6→interface UseTwilioSyncReturn {
     7→  syncClient: SyncClient | null
     8→  isReady: boolean
     9→}
    10→
    11→export function useTwilioSync(): UseTwilioSyncReturn {
    12→  const [syncClient, setSyncClient] = useState<SyncClient | null>(null)
    13→  const [isReady, setIsReady] = useState(false)
    14→  const clientRef = useRef<SyncClient | null>(null)
    15→
    16→  useEffect(() => {
    17→    async function initSync() {
    18→      try {
    19→        const response = await fetch('/api/sync-token')
    20→        const result = await response.json()
    21→
    22→        if (!result.success) {
    23→          throw new Error(result.error || 'Syncトークン取得に失敗しました')
    24→        }
    25→
    26→        const client = new SyncClient(result.data.token)
    27→
    28→        client.on('connectionStateChanged', (state: string) => {
    29→          setIsReady(state === 'connected')
    30→        })
    31→
    32→        clientRef.current = client
    33→        setSyncClient(client)
    34→      } catch (error) {
    35→        console.error('Sync Client初期化に失敗:', error)
    36→      }
    37→    }
    38→
    39→    initSync()
    40→
    41→    return () => {
    42→      if (clientRef.current) {
    43→        clientRef.current.shutdown()
    44→        clientRef.current = null
    45→      }
    46→    }
    47→  }, [])
    48→
    49→  return { syncClient, isReady }
    50→}
    51→

