     1→import { NextRequest, NextResponse } from 'next/server'
     2→
     3→const AUTH_USER = 'twilioroot'
     4→const AUTH_PASS = 'Twilio123'
     5→
     6→// Basic認証を除外するパス（Twilio Webhookやヘルスチェック）
     7→const PUBLIC_PATHS = ['/api/voice', '/api/health']
     8→
     9→function isPublicPath(pathname: string): boolean {
    10→  return PUBLIC_PATHS.some((path) => pathname.startsWith(path))
    11→}
    12→
    13→function unauthorized(): NextResponse {
    14→  return new NextResponse('認証が必要です', {
    15→    status: 401,
    16→    headers: {
    17→      'WWW-Authenticate': 'Basic realm="AI Phone Demo"',
    18→    },
    19→  })
    20→}
    21→
    22→export function middleware(request: NextRequest) {
    23→  // Webhook・ヘルスチェックは認証不要
    24→  if (isPublicPath(request.nextUrl.pathname)) {
    25→    return NextResponse.next()
    26→  }
    27→
    28→  const authHeader = request.headers.get('authorization')
    29→  if (!authHeader || !authHeader.startsWith('Basic ')) {
    30→    return unauthorized()
    31→  }
    32→
    33→  const base64Credentials = authHeader.split(' ')[1]
    34→  const credentials = atob(base64Credentials)
    35→  const [user, pass] = credentials.split(':')
    36→
    37→  if (user === AUTH_USER && pass === AUTH_PASS) {
    38→    return NextResponse.next()
    39→  }
    40→
    41→  return unauthorized()
    42→}
